for code, vals in L.items():
    assert len(vals) == len(KEYS), (code, len(vals), len(KEYS))
    assert len(vals[0]) <= 132, code
    d = OUT / "_locales" / code
    d.mkdir(parents=True, exist_ok=True)
    msgs = {k: {"message": v} for k, v in zip(KEYS, vals)}
    (d / "messages.json").write_text(json.dumps(msgs, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

langs = sorted(N.items(), key=lambda kv: kv[1].lower())
(OUT / "languages.json").write_text(json.dumps([{"code": c, "name": n} for c, n in langs], ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(len(L), "locales:", ", ".join(f"{c} ({n})" for c, n in N.items()))

